-- Reverse of apply.sql: the 2 publishers back to active, Le Patriote back to its sitemap source (crawled source disabled, kept). Generated by Build-Sql.py.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
DO $do$ DECLARE k int; BEGIN
  UPDATE publishers SET feed_status = 'active' WHERE id IN (219, 221) AND feed_status = 'unavailable';
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 2 THEN RAISE EXCEPTION 'publishers: % rows, expected 2', k; END IF;
  UPDATE feeds SET enabled = false WHERE publisher_id = 7291 AND feed_url = 'https://lepatriote.ci/' AND feed_type = 'html' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION 'crawled source: % rows, expected 1', k; END IF;
  UPDATE feeds SET enabled = true WHERE publisher_id = 7291 AND feed_url = 'https://lepatriote.ci/sitemap.xml' AND NOT enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION 'old source: % rows, expected 1', k; END IF;
END $do$;
COMMIT;
